CREATE TYPE booking_state AS ENUM ('requested','confirmed','rejected','cancelled','checked_in','completed','no_show');
CREATE TABLE reservations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), restaurant_id uuid NOT NULL REFERENCES restaurants(id), request_hash text NOT NULL UNIQUE, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, guests integer NOT NULL CHECK(guests BETWEEN 1 AND 30), occasion text NOT NULL, status booking_state NOT NULL DEFAULT 'requested', table_id uuid, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(restaurant_id,table_id) REFERENCES restaurant_tables(restaurant_id,id), CHECK(ends_at>starts_at));
CREATE INDEX reservation_time_idx ON reservations(restaurant_id,table_id,starts_at,ends_at);
CREATE TABLE event_bookings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), restaurant_id uuid NOT NULL REFERENCES restaurants(id), request_hash text NOT NULL UNIQUE, starts_at timestamptz NOT NULL, guests integer NOT NULL CHECK(guests BETWEEN 1 AND 100), occasion text NOT NULL, budget_paise integer CHECK(budget_paise>=0), status booking_state NOT NULL DEFAULT 'requested', created_at timestamptz NOT NULL DEFAULT now());
